import{_ as t,C as s,o as e,c as n,a2 as o,b as l,w as i,a as c,E as d,a3 as u}from"./chunks/framework.CgxQ0r6v.js";const h=JSON.parse('{"title":"4. Capítulo IV: Ejecución y Resultados (Ejemplo Real)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_I/Plantilla_Ejemplo/4_Capitulo_IV_Ejecucion_y_Resultados.md","filePath":"materias/Proyecto_Sociotecnologico_I/Plantilla_Ejemplo/4_Capitulo_IV_Ejecucion_y_Resultados.md"}'),p={name:"materias/Proyecto_Sociotecnologico_I/Plantilla_Ejemplo/4_Capitulo_IV_Ejecucion_y_Resultados.md"};function m(_,a,g,f,b,A){const r=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="_4-capitulo-iv-ejecucion-y-resultados-ejemplo-real" tabindex="-1">4. Capítulo IV: Ejecución y Resultados (Ejemplo Real) <a class="header-anchor" href="#_4-capitulo-iv-ejecucion-y-resultados-ejemplo-real" aria-label="Permalink to &quot;4. Capítulo IV: Ejecución y Resultados (Ejemplo Real)&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Instrucciones de Uso:</strong> Aquí narras lo que realmente hiciste de forma cronológica, presentas tus pruebas técnicas y concluyes si resolviste el problema.</p></div><hr><h2 id="capitulo-iv" tabindex="-1">CAPÍTULO IV <a class="header-anchor" href="#capitulo-iv" aria-label="Permalink to &quot;CAPÍTULO IV&quot;">​</a></h2><h2 id="ejecucion-y-resultados" tabindex="-1">EJECUCIÓN Y RESULTADOS <a class="header-anchor" href="#ejecucion-y-resultados" aria-label="Permalink to &quot;EJECUCIÓN Y RESULTADOS&quot;">​</a></h2><h3 id="_4-1-cronograma-de-ejecucion-diagrama-de-gantt" tabindex="-1">4.1 Cronograma de Ejecución (Diagrama de Gantt) <a class="header-anchor" href="#_4-1-cronograma-de-ejecucion-diagrama-de-gantt" aria-label="Permalink to &quot;4.1 Cronograma de Ejecución (Diagrama de Gantt)&quot;">​</a></h3><p>Las actividades fueron planificadas y ejecutadas a lo largo de un período de 3 semanas, respetando el orden lógico entre el hardware y el software.</p>',7)),(e(),l(u,null,{default:i(()=>[d(r,{id:"mermaid-21",class:"mermaid",graph:"gantt%0A%20%20%20%20title%20Cronograma%20de%20Ejecuci%C3%B3n%20PST%20(Trayecto%20I)%0A%20%20%20%20dateFormat%20%20YYYY-MM-DD%0A%20%20%20%20axisFormat%20%20%25W%0A%20%20%20%20%0A%20%20%20%20section%20FASE%20I%3A%20Hardware%0A%20%20%20%20Limpieza%20F%C3%ADsica%20y%20Soplado%20%3Aa1%2C%202026-10-01%2C%207d%0A%20%20%20%20Reemplazo%20de%20Memorias%20RAM%20%3Aa2%2C%20after%20a1%2C%203d%0A%20%20%20%20%0A%20%20%20%20section%20FASE%20II%3A%20Software%0A%20%20%20%20Instalaci%C3%B3n%20Canaima%20GNU%2FLinux%20%3Ab1%2C%20after%20a2%2C%205d%0A%20%20%20%20Verificaci%C3%B3n%20de%20Red%20Local%20%20%20%20%20%3Ab2%2C%20after%20b1%2C%202d%0A%20%20%20%20%0A%20%20%20%20section%20FASE%20III%3A%20Socializaci%C3%B3n%0A%20%20%20%20Taller%20de%20Ofim%C3%A1tica%20(Docentes)%20%3Ac1%2C%20after%20b2%2C%202d%0A%20%20%20%20Firma%20del%20Acta%20de%20Entrega%20%20%20%20%20%20%3Ac2%2C%20after%20c1%2C%201d%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h3 id="_4-2-narrativa-de-la-ejecucion-bitacora-de-resultados" tabindex="-1">4.2 Narrativa de la Ejecución (Bitácora de Resultados) <a class="header-anchor" href="#_4-2-narrativa-de-la-ejecucion-bitacora-de-resultados" aria-label="Permalink to &quot;4.2 Narrativa de la Ejecución (Bitácora de Resultados)&quot;">​</a></h3><p>Durante la <strong>Semana 1 (Fase de Hardware)</strong>, el equipo investigador desensambló 15 estaciones de trabajo. Se utilizó alcohol isopropílico para la limpieza de los contactos de las memorias RAM y sopladoras industriales para retirar el exceso de polvo, el cual era la causa principal de sobrecalentamiento. Se detectaron 2 fuentes de poder irreparables, por lo que 2 estaciones se fusionaron para lograr al menos 14 operativas de manera estable.</p><p>Durante la <strong>Semana 2 (Fase de Software)</strong>, dando cumplimiento a la Ley de Infogobierno, se procedió a formatear los discos duros mecánicos y a instalar la distribución Canaima GNU/Linux. Las pruebas de estrés arrojaron un tiempo de inicio promedio de 45 segundos, lo que representa una mejora del 300% respecto a los tiempos de carga previos al mantenimiento.</p><p>Durante la <strong>Semana 3 (Fase de Socialización)</strong>, se impartió un taller teórico-práctico de 4 horas académicas dirigido a la directora del plantel y 4 docentes, enfocándose en la transición de Microsoft Office a LibreOffice.</p><h3 id="_4-3-analisis-de-resultados-e-indicadores" tabindex="-1">4.3 Análisis de Resultados e Indicadores <a class="header-anchor" href="#_4-3-analisis-de-resultados-e-indicadores" aria-label="Permalink to &quot;4.3 Análisis de Resultados e Indicadores&quot;">​</a></h3><p>Al culminar las actividades, se contrastaron los resultados con los indicadores propuestos en la MML:</p><ul><li><strong>Indicador Propuesto:</strong> Operatividad de 15 equipos.</li><li><strong>Resultado Logrado:</strong> Operatividad de 14 equipos (93% de cumplimiento técnico). La variación se debió al daño físico irrecuperable de fuentes de poder (Causa de fuerza mayor).</li><li><strong>Indicador Social:</strong> Capacitación de 5 docentes.</li><li><strong>Resultado Logrado:</strong> El 100% de los docentes convocados asistieron y firmaron el acta de aprobación del taller de LibreOffice.</li></ul><h3 id="_4-4-conclusiones-y-recomendaciones" tabindex="-1">4.4 Conclusiones y Recomendaciones <a class="header-anchor" href="#_4-4-conclusiones-y-recomendaciones" aria-label="Permalink to &quot;4.4 Conclusiones y Recomendaciones&quot;">​</a></h3><p>Se concluye que el mantenimiento preventivo y la migración a Software Libre es una solución altamente efectiva y de bajo costo para instituciones educativas públicas. El problema central (alta inoperatividad) fue mitigado en un 93%, reactivando las capacidades ofimáticas de la institución.</p><p><strong>Se recomienda a la comunidad:</strong></p><ol><li>Adquirir regletas con supresor de picos o reguladores de voltaje (UPS) para proteger las fuentes de poder recién reparadas.</li><li>Establecer una política interna que prohíba el consumo de alimentos o bebidas dentro del área del laboratorio para preservar la limpieza física del hardware.</li></ol>',11))])}const E=t(p,[["render",m]]);export{h as __pageData,E as default};
